function tickClock(){const d=new Date();document.getElementById("sydneyTime").textContent=new Intl.DateTimeFormat("en-AU",{hour:"numeric",minute:"2-digit"}).format(d);document.getElementById("athensTime").textContent=new Intl.DateTimeFormat("en-GB",{timeZone:"Europe/Athens",hour:"2-digit",minute:"2-digit",hour12:false}).format(d);document.getElementById("date").textContent=d.toLocaleDateString("en-AU",{weekday:"short",day:"numeric",month:"short"}).toUpperCase()}tickClock();setInterval(tickClock,30000);
async function loadWeather(){const icon=c=>c===0?"☀":c<4?"☁":c<60?"🌫":c<80?"🌧":"⛈";try{const [sr,ar]=await Promise.all([fetch("https://api.open-meteo.com/v1/forecast?latitude=-33.8688&longitude=151.2093&current=temperature_2m,weather_code&timezone=Australia%2FSydney"),fetch("https://api.open-meteo.com/v1/forecast?latitude=37.9838&longitude=23.7275&current=temperature_2m,weather_code&timezone=Europe%2FAthens")]);const j=await sr.json(),a=await ar.json();document.getElementById("sydneyWeather").textContent=icon(j.current.weather_code)+" "+Math.round(j.current.temperature_2m)+"°";document.getElementById("athensWeather").textContent=icon(a.current.weather_code)+" "+Math.round(a.current.temperature_2m)+"°"}catch(e){document.getElementById("sydneyWeather").textContent="--°";document.getElementById("athensWeather").textContent="--°"}}loadWeather();setInterval(loadWeather,900000);
const mobileSearchBtn=document.getElementById("mobileSearchBtn");
if(mobileSearchBtn){
 mobileSearchBtn.onclick=()=>{
   const bar=document.querySelector(".topline"),input=document.getElementById("search");
   bar.classList.toggle("search-open");
   if(bar.classList.contains("search-open")){input.focus()}
   else{input.value="";input.dispatchEvent(new Event("input"))}
 };
}
document.addEventListener("keydown",e=>{
 if(e.key==="Escape"){
   const bar=document.querySelector(".topline");
   if(bar&&bar.classList.contains("search-open")){bar.classList.remove("search-open");document.getElementById("search").blur()}
 }
});
